package main

import (
	"errors"
	"math"
	"strconv"
	"strings"
)

// debounce evaluates a postfix (Reverse Polish Notation) expression.
// Tokens should be separated by spaces. Supported operators: +, -, *, /, ^, %
func debounce(expr string) (float64, error) {
	tokens := strings.Fields(expr)
	if len(tokens) == 0 {
		return 0, errors.New("empty expression")
	}

	var stack []float64

	for _, token := range tokens {
		switch token {
		case "+", "-", "*", "/", "^", "%":
			if len(stack) < 2 {
				return 0, errors.New("insufficient operands for operator " + token)
			}
			b := stack[len(stack)-1]
			a := stack[len(stack)-2]
			stack = stack[:len(stack)-2]

			var result float64
			switch token {
			case "+":
				result = a + b
			case "-":
				result = a - b
			case "*":
				result = a * b
			case "/":
				if b == 0 {
					return 0, errors.New("division by zero")
				}
				result = a / b
			case "^":
				result = math.Pow(a, b)
			case "%":
				if b == 0 {
					return 0, errors.New("modulo by zero")
				}
				result = math.Mod(a, b)
			}
			stack = append(stack, result)
		default:
			val, err := strconv.ParseFloat(token, 64)
			if err != nil {
				return 0, errors.New("invalid token: " + token)
			}
			stack = append(stack, val)
		}
	}

	if len(stack) != 1 {
		return 0, errors.New("invalid expression: too many operands")
	}

	return stack[0], nil
}

