package choucisan

import (
	"math"
	"testing"
)

func TestDebounce(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		want    float64
		wantErr bool
	}{
		// Basic arithmetic
		{"simple addition", "3 4 +", 7, false},
		{"simple subtraction", "10 5 -", 5, false},
		{"simple multiplication", "6 7 *", 42, false},
		{"simple division", "20 4 /", 5, false},

		// Order matters in postfix
		{"subtraction order", "3 10 -", -7, false},
		{"division order", "4 20 /", 0.2, false},

		// Chained operations
		{"three operands add", "3 4 + 5 +", 12, false},
		{"three operands multiply", "2 3 * 4 *", 24, false},
		{"mixed add and multiply", "3 4 2 * +", 11, false},
		{"mixed subtract and divide", "10 6 2 / -", 7, false},
		{"all four basic ops", "1 2 + 3 4 - *", -3, false},

		// Exponentiation
		{"simple exponent", "2 3 ^", 8, false},
		{"zero exponent", "5 0 ^", 1, false},
		{"exponent with multiply", "2 3 2 ^ *", 18, false},
		{"chained exponents (right assoc)", "2 3 2 ^ ^", 512, false},

		// Modulo
		{"simple modulo", "10 3 %", 1, false},
		{"modulo exact", "10 5 %", 0, false},
		{"modulo with negative", "-7 3 %", -1, false},

		// Decimals
		{"decimal addition", "3.14 2.0 +", 5.14, false},
		{"decimal multiplication", "2.5 4.0 *", 10, false},
		{"decimal division", "7.5 2.5 /", 3, false},

		// Negative numbers
		{"negative operand", "-3 4 +", 1, false},
		{"two negatives", "-3 -4 +", -7, false},
		{"negative result", "3 10 -", -7, false},

		// Single operand
		{"single number", "42", 42, false},
		{"single negative", "-7", -7, false},
		{"single decimal", "3.14", 3.14, false},
		{"single zero", "0", 0, false},

		// Zero handling
		{"add zero", "5 0 +", 5, false},
		{"multiply by zero", "5 0 *", 0, false},

		// Complex expressions
		{"complex 1", "3 4 + 2 * 1 -", 13, false},
		{"complex 2", "2 3 ^ 1 + 2 /", 4.5, false},
		{"complex 3", "10 3 % 2 ^ 3 +", 4, false},
		{"quadratic formula style", "0 4 - 16 20 - sqrt + 2 /", 0, true}, // sqrt not supported

		// Large numbers
		{"large numbers", "1000000 2000000 +", 3000000, false},

		// Floating point precision
		{"float precision", "0.1 0.2 +", 0.30000000000000004, false},

		// Error cases
		{"empty string", "", 0, true},
		{"only spaces", "   ", 0, true},
		{"insufficient operands", "3 +", 0, true},
		{"too many operands", "3 4 5 +", 0, true},
		{"invalid token", "3 abc +", 0, true},
		{"division by zero", "5 0 /", 0, true},
		{"modulo by zero", "5 0 %", 0, true},
		{"only operator", "+", 0, true},
		{"two operators", "3 4 + *", 0, true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := debounce(tt.input)
			if (err != nil) != tt.wantErr {
				t.Errorf("debounce(%q) error = %v, wantErr %v", tt.input, err, tt.wantErr)
				return
			}
			if !tt.wantErr && math.Abs(got-tt.want) > 1e-9 {
				t.Errorf("debounce(%q) = %v, want %v", tt.input, got, tt.want)
			}
		})
	}
}

func TestDebounceDivisionByZero(t *testing.T) {
	_, err := debounce("5 0 /")
	if err == nil {
		t.Error("expected error for division by zero")
	}
	if err.Error() != "division by zero" {
		t.Errorf("unexpected error message: %v", err)
	}
}

func TestDebounceModuloByZero(t *testing.T) {
	_, err := debounce("5 0 %")
	if err == nil {
		t.Error("expected error for modulo by zero")
	}
	if err.Error() != "modulo by zero" {
		t.Errorf("unexpected error message: %v", err)
	}
}

func TestDebounceInsufficientOperands(t *testing.T) {
	tests := []string{"+", "-", "*", "/", "^", "%", "3 +", "3 -"}
	for _, input := range tests {
		_, err := debounce(input)
		if err == nil {
			t.Errorf("expected error for %q", input)
		}
	}
}

func TestDebounceInvalidToken(t *testing.T) {
	tests := []string{"3 abc +", "hello 2 +", "3 4 ++", "1 2 @"}
	for _, input := range tests {
		_, err := debounce(input)
		if err == nil {
			t.Errorf("expected error for %q", input)
		}
	}
}

func TestDebounceTooManyOperands(t *testing.T) {
	_, err := debounce("3 4 5 +")
	if err == nil {
		t.Error("expected error for too many operands")
	}
}

func TestDebounceComplexExpressions(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  float64
	}{
		// (3 + 4) * (2 - 1) = 7
		{"two subexpressions multiply", "3 4 + 2 1 - *", 7},
		// 2^3 + 4*5 = 8 + 20 = 28
		{"exponent and multiply add", "2 3 ^ 4 5 * +", 28},
		// (10 - 3) * (8 / 4) = 7 * 2 = 14
		{"subtraction and division", "10 3 - 8 4 / *", 14},
		// ((2 + 3) * 4) - (6 / 2) = 20 - 3 = 17
		{"nested subexpressions", "2 3 + 4 * 6 2 / -", 17},
		// 3^2 + 4^2 = 9 + 16 = 25
		{"sum of squares", "3 2 ^ 4 2 ^ +", 25},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := debounce(tt.input)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if math.Abs(got-tt.want) > 1e-9 {
				t.Errorf("debounce(%q) = %v, want %v", tt.input, got, tt.want)
			}
		})
	}
}
